## spe/evals/harness/priority-grader.js

```js
// Priority comparison for SPE graders. Added after r03 (F7).
// Compares priorities after trimming whitespace and ignoring case.
// It does not map word labels such as "High" to P-codes. See disagreements D-r03-2.

function normalizePriority(value) {
  if (value === null || value === undefined) return "";
  return String(value).trim().toUpperCase();
}

function priorityMatches(predicted, expected) {
  const p = normalizePriority(predicted);
  const e = normalizePriority(expected);
  if (p === "" || e === "") return false;
  return p === e;
}

function selftest() {
  const cases = [
    ["P1", "P1", true],    // oracle
    ["p1", "P1", true],    // case variant (the F7 bug)
    [" P1 ", "P1", true],  // whitespace variant
    ["P2", "P1", false],   // wrong answer
    ["", "P1", false],     // empty answer
    [null, "P1", false],   // missing answer
    ["High", "P1", false], // word label is not mapped
  ];
  const failures = cases.filter(([p, e, want]) => priorityMatches(p, e) !== want);
  if (failures.length > 0) {
    throw new Error("priority grader selftest failed: " + JSON.stringify(failures));
  }
  return { passed: cases.length };
}

module.exports = { normalizePriority, priorityMatches, selftest };
```

## spe/evals/harness/r03-regrade.js

```js
// Regrades saved r03 trial outputs with the fixed priority grader (F7).
// Reads trial outputs only. Does not rerun trials. Does not touch predictions.
const fs = require("fs");
const path = require("path");
const { priorityMatches, selftest } = require("./priority-grader");

const ROUND = process.argv[2] || "r03";
const inFile = path.join("spe", "evals", "results", ROUND, "trials.jsonl");
const outFile = path.join("spe", "evals", "results", `${ROUND}-regraded.json`);

selftest();

const trials = fs.readFileSync(inFile, "utf8")
  .split("\n").filter(Boolean).map((line) => JSON.parse(line))
  .filter((t) => !t.voided);

const byConfig = {};
for (const t of trials) {
  const c = (byConfig[t.config] ||= { n: 0, rawCorrect: 0, fixedCorrect: 0 });
  c.n += 1;
  if (t.output.priority === t.expected.priority) c.rawCorrect += 1;
  if (priorityMatches(t.output.priority, t.expected.priority)) c.fixedCorrect += 1;
}

const result = { round: ROUND, metric: "priority_accuracy", configs: {} };
for (const [config, c] of Object.entries(byConfig)) {
  result.configs[config] = {
    trials: c.n,
    original: +(c.rawCorrect / c.n).toFixed(2),
    regraded: +(c.fixedCorrect / c.n).toFixed(2),
  };
}
fs.writeFileSync(outFile, JSON.stringify(result, null, 2) + "\n");
console.log(JSON.stringify(result, null, 2));
```

## spe/failures.md (append after F6)

```markdown
## F7. Grader compared priorities as case-sensitive strings

- **Kind:** grader bug (harness), found after the run
- **Round:** r03
- **What:** The r03 grader compared priority values with strict string equality. A trial that answered "p1" for an expected "P1" was scored wrong. This pushed C2 priority accuracy down from 0.79 to 0.64.
- **How to spot it:** Read failed trials where the answer and the key differ only in case or whitespace. Compare the original score with the regraded score. A gap means the grader is scoring format instead of content.
- **Seen in:** r03 C2 transcripts, found while reading transcripts at close-out. The r02 control regrade with the fixed grader did not change.
- **Fix:** `spe/evals/harness/priority-grader.js` normalizes with trim and uppercase before comparing. Its selftest now includes case and whitespace variants. Every grader selftest from r04 on must include format variants of the oracle answer. The selftest gate missed this because it only tested the exact oracle string.
- **Numbers:**

| Metric | Config | Original | Regraded |
|---|---|---|---|
| priority_accuracy | C2 | 0.64 | 0.79 |
```

